-- Apply explicitly to a reviewed tenant database. Never enables the runtime automatically.
CREATE TABLE IF NOT EXISTS telephony_runtime_policy (id TINYINT NOT NULL PRIMARY KEY, enabled TINYINT NOT NULL DEFAULT 0, allow_change_reason TINYINT NOT NULL DEFAULT 0, preflight_hash VARCHAR(64) NULL) ENGINE=InnoDB;
INSERT IGNORE INTO telephony_runtime_policy(id,enabled) VALUES(1,0);
CREATE TABLE IF NOT EXISTS telephony_operator_state (operator_id INT NOT NULL PRIMARY KEY,state VARCHAR(16) NOT NULL DEFAULT 'available',reason_id INT NULL,pause_id BIGINT NULL,pending_schedule_id INT NULL,active_call_id CHAR(36) NULL,version INT NOT NULL DEFAULT 0,updated_at DATETIME NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS telephony_calls (id CHAR(36) NOT NULL PRIMARY KEY,sequence_id BIGINT NOT NULL AUTO_INCREMENT UNIQUE,operator_id INT NOT NULL,direction VARCHAR(12) NOT NULL,number VARCHAR(64) NOT NULL,extension VARCHAR(32) NOT NULL DEFAULT '',schedule_id INT NULL,customer_id INT NULL,history_id INT NULL,state VARCHAR(20) NOT NULL,prepared_at DATETIME NOT NULL,sent_at DATETIME NULL,ringing_at DATETIME NULL,answered_at DATETIME NULL,ended_at DATETIME NULL,updated_at DATETIME NOT NULL,KEY operator_sequence(operator_id,sequence_id),KEY schedule_calls(schedule_id),KEY operator_time(operator_id,prepared_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS telephony_call_events (id CHAR(36) NOT NULL PRIMARY KEY,call_id CHAR(36) NOT NULL,type VARCHAR(20) NOT NULL,occurred_at DATETIME NOT NULL,received_at DATETIME NOT NULL,detail VARCHAR(1000) NULL,sip_call_id VARCHAR(255) NULL,KEY call_events(call_id,occurred_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS telephony_call_reviews (call_id CHAR(36) NOT NULL PRIMARY KEY,operator_id INT NOT NULL,rating VARCHAR(8) NULL,comment VARCHAR(1000) NOT NULL DEFAULT '',version INT NOT NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS telephony_pause_segments (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,operator_id INT NOT NULL,reason_id INT NOT NULL,reason_name VARCHAR(255) NOT NULL,max_seconds INT NOT NULL DEFAULT 0,productive TINYINT NOT NULL DEFAULT 0,started_at DATETIME NOT NULL,ended_at DATETIME NULL,duration_seconds INT NULL,exceeded_seconds INT NULL,operation_id VARCHAR(64) NOT NULL,KEY operator_pause(operator_id,started_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS telephony_runtime_operations (operation_id CHAR(36) NOT NULL PRIMARY KEY,actor_id INT NOT NULL,kind VARCHAR(24) NOT NULL,request_hash CHAR(64) NOT NULL,result_json LONGTEXT NOT NULL,created_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS telephony_pbx_members (operator_id INT NOT NULL,queue_name VARCHAR(128) NOT NULL,member_interface VARCHAR(128) NOT NULL,enabled TINYINT NOT NULL DEFAULT 0,PRIMARY KEY(operator_id,queue_name,member_interface)) ENGINE=InnoDB DEFAULT CHARSET=ascii COLLATE=ascii_bin;
CREATE TABLE IF NOT EXISTS telephony_pbx_intents (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,operation_id VARCHAR(64) NOT NULL,operator_id INT NOT NULL,queue_name VARCHAR(128) NOT NULL,member_interface VARCHAR(128) NOT NULL,paused TINYINT NOT NULL,status VARCHAR(16) NOT NULL,detail VARCHAR(200) NULL,created_at DATETIME NOT NULL,updated_at DATETIME NULL,KEY actor_pending(operator_id,status,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
